import{_ as l,a0 as u,w as a,s as p,ao as r,I as s,x as n,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"试试只用U盘加载Linux系统 | LCTT x X-CMD","titleTemplate":false,"description":"试试只用U盘加载Linux系统 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"试试只用U盘加载Linux系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"试试只用U盘加载Linux系统 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141030 Test drive Linux with nothing but a flash drive","title":"试试只用U盘加载Linux系统","tag":"201502","desc":""},"relativePath":"201502/20141030 Test drive Linux with nothing but a flash drive.md","filePath":"[post].md"}'),d={name:"201502/20141030 Test drive Linux with nothing but a flash drive.md"};function g(f,t,m,x,T,b){const i=u("Link");return a(),p("div",null,[t[23]||(t[23]=r('<h1 id="试试只用u盘加载linux系统" tabindex="-1">试试只用U盘加载Linux系统 <a class="header-anchor" href="#试试只用u盘加载linux系统" aria-label="Permalink to “试试只用U盘加载Linux系统”">​</a></h1><p>也许你听过Linux并对它有点好奇，终于想要实际体验一下，但可能不知道从哪儿开始。</p><p>很可能你已经在网上搜索过一些信息，然后遇到一些像双系统和虚拟机这样的词汇。它们对你来说也许太专业了，所以你肯定不会仅仅为了尝试一下Linux而牺牲正在使用的操作系统。那我们该怎么办？</p><p>如果你手上正好有个U盘的话，那就可以试试做一个USB Linux启动盘。它是一个包含了整个操作系统并可以直接引导开机的U盘。创建它并不需要什么专业技术能力，让我们来看看怎么做，以及如何从USB引导进入Linux系统。</p><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/OSDC_Penguin_Image_520x292_12324207_0714_mm_v1a.png" alt="Penguins gathered together: Linux for the win"></p><h3 id="你需要准备的" tabindex="-1">你需要准备的 <a class="header-anchor" href="#你需要准备的" aria-label="Permalink to “你需要准备的”">​</a></h3><p>除了一台台式机或笔记本电脑外，你还需要：</p>',7)),s("ul",null,[t[6]||(t[6]=s("li",null,"一个空白的U盘-最好容量能有4GB或更多。",-1)),s("li",null,[t[1]||(t[1]=n("一个你想尝试的Linux发行版",-1)),e(i,{href:"http://en.wikipedia.org/wiki/ISO_image"},{default:o(()=>[...t[0]||(t[0]=[n("ISO镜像",-1)])]),_:1}),t[2]||(t[2]=n("（一种把所有磁盘内容打包起来的档案文件）。待会再详细介绍。",-1))]),s("li",null,[t[4]||(t[4]=n("一个叫",-1)),e(i,{href:"http://unetbootin.sourceforge.net/"},{default:o(()=>[...t[3]||(t[3]=[n("Unetbootin",-1)])]),_:1}),t[5]||(t[5]=n("的应用程序，它是一个开源的，跨平台的工具，用来创建USB启动盘。运行它并不需要启动Linux。在下面的教程中，我是在MacBook上运行的Unetbootiin（LCTT 译注：它还有 Windows 和 Linux 版本）。",-1))])]),t[24]||(t[24]=r('<h3 id="开始干活" tabindex="-1">开始干活 <a class="header-anchor" href="#开始干活" aria-label="Permalink to “开始干活”">​</a></h3><p>把U盘插到你电脑的USB端口上，然后启动Unetbootin。然后会要求你输入当前电脑的登录密码。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-main.png" alt="Unetbootin main window"></p><p>还记得之前提到的ISO镜像文件吗？有两种方式可以获得：要么自己从你想尝试的Linux发行版网站上下载，或者让Unetbootin帮你下载。如果选后者，在窗口顶部点击<strong>选择发行版</strong>，选择你想下载的发行版，然后点击<strong>选择版本</strong>来选择你希望尝试的发行版版本。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-download-distro.png" alt="Downloading a Linux distribution"></p><p>或者，你也可以自己下载发行版。通常，我想尝试的Linux发行版都没有在列表中。如果选择自己下载，那么点击<strong>磁盘镜像</strong>，然后点击按钮来选择你下载好的.iso文件。</p><p>注意到下面的选项<strong>预留每次重新启动后保存文件的空间（仅Ubuntu有效）</strong>吗？如果你尝试的是Ubuntu或它的任一个衍生版（比如Lubuntu或Xubuntu），你可以在U盘上留出几M空间用来保存文件，比如网页书签或你自己创建的文档。当用这个U盘下次启动Ubuntu的时候，你可以继续使用这些文件。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-ready-to-go.png" alt="Ready to create a live USB"></p><p>在加载好ISO镜像后，点击<strong>确定</strong>。Unetbootin大概需要不到10分钟来创建USB启动盘。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-creating-disk.png" alt="Creating the live USB"></p><h3 id="检验usb启动盘" tabindex="-1">检验USB启动盘 <a class="header-anchor" href="#检验usb启动盘" aria-label="Permalink to “检验USB启动盘”">​</a></h3>',11)),s("p",null,[t[8]||(t[8]=n("这个时候，你需要拥抱一下自己内在的极客精神。这不会太难，不过你将需要进入",-1)),e(i,{href:"http://en.wikipedia.org/wiki/BIOS"},{default:o(()=>[...t[7]||(t[7]=[n("BIOS",-1)])]),_:1}),t[9]||(t[9]=n("去偷看一下你的电脑内部空间。你的电脑的BIOS会加载各种硬件，并控制电脑操作系统的引导或启动。",-1))]),t[25]||(t[25]=r('<p>BIOS通常会按这个顺序搜索操作系统（或者类似的顺序）：硬盘，然后是CD/DVD光驱，然后是外部存储设备。你需要调整这个顺序，让外部存储设备（在这里，指的是你的U盘启动盘）成为BIOS第一个搜索的设备。</p><p>要做到这一点，请把U盘插到电脑上再重启电脑。在看到提示信息<strong>Press F2 to enter setup</strong>之后，按它要求的做。在有的电脑上，这个键可能是F10。</p><p>在BIOS里，用键盘上的向右方向键切换到<strong>Boot</strong>菜单。然后你将看到你电脑上的驱动器列表。使用键盘上的向下方向键选中名字为<strong>USB HDD</strong>的选项，然后按下<strong>F6</strong>移动这个选项到列表的顶部。</p><p>完成后，按下<strong>F10</strong>来保存改动。然后你会从BIOS里被踢出来，然后电脑会自己启动。等一小会，你就会看到一个你正在尝试的Linux发行版的启动菜单。选择<strong>Run without installing</strong>（或者最类似的选项）。</p><p>在进入桌面后，你可以连接上无线或有线网络，看看网页，试一试预装的软件。你还可以看看，比如说，你的打印机或扫描仪是否能在你试的这个发行版下正常工作。你要是真的想不开，也可以去摸一下命令行。</p><h3 id="能干什么" tabindex="-1">能干什么 <a class="header-anchor" href="#能干什么" aria-label="Permalink to “能干什么”">​</a></h3><p>根据你尝试的Linux发行版和你使用的U盘的速度，操作系统可能会需要较长的时间来加载，而且很可能比直接装到硬盘上会慢一点。</p><p>还有，你也只能运行Linux发行版里预装好的基本软件。通常会有网页浏览器，一个文字处理软件，一个文本编辑器，一个媒体播放器，一个相片浏览器，以及一套实用工具。这些应该足够给你使用Linux的感觉了。</p><p>如果你决定使用Linux，你可以双击安装器从U盘安装到硬盘。</p><hr>',10)),s("p",null,[t[11]||(t[11]=n("via: ",-1)),e(i,{href:"https://opensource.com/life/14/10/test-drive-linux-nothing-flash-drive"},{default:o(()=>[...t[10]||(t[10]=[n("https://opensource.com/life/14/10/test-drive-linux-nothing-flash-drive",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/scottnesbitt"},{default:o(()=>[...t[12]||(t[12]=[n("Scott Nesbitt",-1)])]),_:1}),t[16]||(t[16]=n(" 译者：",-1)),e(i,{href:"https://github.com/zpl1025"},{default:o(()=>[...t[13]||(t[13]=[n("zpl1025",-1)])]),_:1}),t[17]||(t[17]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[20]||(t[20]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原创翻译，",-1)),e(i,{href:"http://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中国",-1)])]),_:1}),t[22]||(t[22]=n(" 荣誉推出",-1))])])}const h=l(d,[["render",g]]);export{S as __pageData,h as default};
